1	/*
2	 * Continuous step-lane background tests (Group G2).
3	 *
4	 * Loaded by tests/frontend/test_app_pure.mjs after its shared DOM stub is
5	 * installed. Exposes `registerStepLaneContinuityTests({app, check, findOne,
6	 * findAll})` so the parent harness drives the same check() reporter.
7	 *
8	 * This is a CSS-only feature (方案A: 背景连续、块仍分明): the per-step lane colour,
9	 * formerly painted as a per-record island background, is now carried on a
10	 * --step-lane custom property and rendered through a z-index:-1 ::before underlay
11	 * that overflows ±7px into the .history-detail gap:14px so adjacent same-step
12	 * records' lanes meet edge-to-edge and read as one continuous band. The
13	 * assertions are read-only string/rule checks against style.css.
14	 *
15	 * Coverage:
16	 *   (a) The 13 per-type rules carry --step-lane (with their original colour /
17	 *       alpha) and keep their border-left-color, and no longer paint `background`
18	 *       directly on the record box.
19	 *   (b) A shared ::before underlay rule exists with top:-7px / bottom:-7px and
20	 *       z-index:-1, consuming background-color:var(--step-lane).
21	 *   (c) Boundary / container-edge overflow-suppression rules exist (first block
22	 *       no upward overflow, last block no downward overflow, container first /
23	 *       last child no overflow past the edge).
24	 *   (d) The geometry rule still excludes .step-status-row / .group-status-marker.
25	 */
26	import assert from "node:assert/strict";
27	import fs from "node:fs";
28	import path from "node:path";
29	import { fileURLToPath } from "node:url";
30	
31	const HERE = path.dirname(fileURLToPath(import.meta.url));
32	const STYLE_CSS = path.join(
33	  HERE, "..", "..", "src", "se3", "server", "static", "style.css");
34	const CSS = fs.readFileSync(STYLE_CSS, "utf8");
35	
36	// The 13 content step types and their original lane colour/alpha (must be
37	// preserved byte-for-byte, only moved from `background:` to `--step-lane:`).
38	const PER_TYPE = [
39	  ["discovery", "rgba(91, 143, 214, 0.07)"],
40	  ["analyze", "rgba(63, 169, 191, 0.07)"],
41	  ["plan", "rgba(138, 130, 224, 0.08)"],
42	  ["confirm", "rgba(111, 134, 201, 0.07)"],
43	  ["implement", "rgba(87, 168, 106, 0.07)"],
44	  ["test", "rgba(63, 174, 154, 0.07)"],
45	  ["self_check", "rgba(200, 154, 70, 0.08)"],
46	  ["verify_spec", "rgba(208, 130, 78, 0.08)"],
47	  ["update_spec", "rgba(84, 174, 196, 0.07)"],
48	  ["spec_gate", "rgba(194, 161, 63, 0.08)"],
49	  ["version_analyze", "rgba(168, 127, 196, 0.08)"],
50	  ["commit", "rgba(121, 168, 63, 0.07)"],
51	  ["summarize", "rgba(130, 139, 152, 0.09)"],
52	];
53	
54	// Extract the body `{...}` of the first rule whose selector contains `needle`.
55	function ruleBody(css, needle) {
56	  const at = css.indexOf(needle);
57	  assert.notEqual(at, -1, `missing rule containing: ${needle}`);
58	  const open = css.indexOf("{", at);
59	  assert.notEqual(open, -1, `no '{' after: ${needle}`);
60	  const close = css.indexOf("}", open);
61	  assert.notEqual(close, -1, `no '}' after: ${needle}`);
62	  return css.slice(open + 1, close);
63	}
64	
65	export function registerStepLaneContinuityTests(ctx) {
66	  const { check } = ctx;
67	
68	  // ---- (a) per-type rules carry --step-lane, keep border-left, drop bg ------
69	  for (const [type, colour] of PER_TYPE) {
70	    check(`G2 step-type-${type} carries --step-lane and keeps border-left`, () => {
71	      const sel =
72	        `.history-detail .conv-record.step-type-${type}:not(.step-status-row):not(.group-status-marker)`;
73	      const body = ruleBody(CSS, sel);
74	      assert.ok(
75	        body.includes(`--step-lane: ${colour}`),
76	        `${type} rule must set --step-lane: ${colour}`);
77	      assert.ok(
78	        body.includes(`border-left-color: var(--step-${type})`),
79	        `${type} rule must keep its border-left-color`);
80	      // No longer paints a plain `background` on the record box itself.
81	      assert.ok(
82	        !/(^|[\s;{])background\s*:/.test(body),
83	        `${type} rule must not paint background directly (lane moved to ::before)`);
84	    });
85	  }
86	
87	  // ---- (b) shared ::before underlay with ±7px overflow and z-index:-1 -------
88	  check("G2 step-type ::before underlay overflows ±7px under content", () => {
89	    const body = ruleBody(
90	      CSS,
91	      `.history-detail .conv-record[class*="step-type-"]:not(.step-status-row):not(.group-status-marker)::before`);
92	    assert.ok(body.includes("top: -7px"), "::before must overflow top: -7px");
93	    assert.ok(body.includes("bottom: -7px"), "::before must overflow bottom: -7px");
94	    assert.ok(body.includes("left: 0"), "::before must span left: 0");
95	    assert.ok(body.includes("right: 0"), "::before must span right: 0");
96	    assert.ok(/z-index:\s*-1/.test(body), "::before must sit at z-index: -1 (below content)");
97	    assert.ok(
98	      body.includes("background-color: var(--step-lane)"),
99	      "::before must paint background-color: var(--step-lane)");
100	    assert.ok(body.includes('content: ""'), "::before must set content");
101	    assert.ok(/position:\s*absolute/.test(body), "::before must be absolutely positioned");
102	  });
103	
104	  check("G2 step-type record establishes a positioning context", () => {
105	    const body = ruleBody(
106	      CSS,
107	      `.history-detail .conv-record[class*="step-type-"]:not(.step-status-row):not(.group-status-marker) {`);
108	    assert.ok(/position:\s*relative/.test(body),
109	      "content step-type record must be position: relative for the ::before underlay");
110	  });
111	
112	  // ---- (b2) visibility contract: record must form a STACKING CONTEXT --------
113	  // Pins the fix for the self-check critical issue. The lane is painted by a
114	  // z-index:-1 ::before underlay. If .conv-record only has position:relative
115	  // (no stacking context), that negative-z pseudo resolves against the nearest
116	  // ancestor stacking context (.history-view / #flow-view) and is drawn BEHIND
117	  // the opaque `background: var(--bg)` of the intervening panes
118	  // (.history-detail-pane / .flow-main) — so the lane renders nothing. The
119	  // record MUST therefore form its own stacking context (isolation: isolate,
120	  // or an explicit non-auto z-index) so the underlay paints behind the
121	  // record's own content but ABOVE the pane background and stays visible.
122	  check("G2 step-type record forms a stacking context so the underlay is visible", () => {
123	    const body = ruleBody(
124	      CSS,
125	      `.history-detail .conv-record[class*="step-type-"]:not(.step-status-row):not(.group-status-marker) {`);
126	    const formsStackingContext =
127	      /isolation:\s*isolate/.test(body) ||
128	      // An explicit non-auto z-index on a positioned element also forms one.
129	      /z-index:\s*-?\d/.test(body);
130	    assert.ok(
131	      formsStackingContext,
132	      "content step-type record must form a stacking context (isolation: isolate " +
133	      "or an explicit z-index) so the z-index:-1 lane underlay paints above the " +
134	      "ancestor pane's opaque var(--bg) background instead of being hidden behind it");
135	  });
136	
137	  // The intervening panes really do carry an opaque background — this is the
138	  // ancestor that would hide an un-contained underlay. Lock it so the test
139	  // above keeps its rationale: if these ever become transparent the stacking
140	  // requirement could be relaxed, but today it is mandatory.
141	  check("G2 intervening panes carry an opaque var(--bg) background", () => {
142	    const detailPane = ruleBody(CSS, ".history-detail-pane");
143	    assert.ok(/background:\s*var\(--bg\)/.test(detailPane),
144	      ".history-detail-pane must carry the opaque var(--bg) background the underlay must paint above");
145	  });
146	
147	  // ---- (c) boundary / container-edge suppression ---------------------------
148	  check("G2 step first block does not overflow upward across the header", () => {
149	    const body = ruleBody(
150	      CSS, ".history-detail .history-step-header + .conv-record::before");
151	    assert.ok(/top:\s*0/.test(body), "first block ::before must reset top to 0");
152	  });
153	  check("G2 step last block does not overflow downward across the next header", () => {
154	    const body = ruleBody(
155	      CSS, ".history-detail .conv-record:has(+ .history-step-header)::before");
156	    assert.ok(/bottom:\s*0/.test(body), "last block ::before must reset bottom to 0");
157	  });
158	  check("G2 container first/last child does not overflow past the edge", () => {
159	    const firstBody = ruleBody(
160	      CSS, ".history-detail > .conv-record:first-child::before");
161	    assert.ok(/top:\s*0/.test(firstBody), "first child ::before must reset top to 0");
162	    const lastBody = ruleBody(
163	      CSS, ".history-detail > .conv-record:last-child::before");
164	    assert.ok(/bottom:\s*0/.test(lastBody), "last child ::before must reset bottom to 0");
165	  });
166	
167	  // ---- (d) status / DAG markers stay excluded ------------------------------
168	  check("G2 lane geometry still excludes status / group markers", () => {
169	    // Both the position:relative base rule and the ::before rule must carry the
170	    // :not(.step-status-row):not(.group-status-marker) exclusion.
171	    const baseSel =
172	      `.history-detail .conv-record[class*="step-type-"]:not(.step-status-row):not(.group-status-marker) {`;
173	    const beforeSel =
174	      `.history-detail .conv-record[class*="step-type-"]:not(.step-status-row):not(.group-status-marker)::before`;
175	    assert.notEqual(CSS.indexOf(baseSel), -1,
176	      "base geometry rule must exclude .step-status-row/.group-status-marker");
177	    assert.notEqual(CSS.indexOf(beforeSel), -1,
178	      "::before geometry rule must exclude .step-status-row/.group-status-marker");
179	  });
180	}
